B.a2g=s(["\ubcf8\uc778\uc740 \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\uc774 \uc218\uc911\uc5d0\uc11c \uc555\ucd95\ub41c \ud638\ud761 \uae30\uccb4\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc774\ub8e8\uc5b4\uc9c0\ub294 \ud65c\ub3d9\uc774\uba70, \ucda9\ubd84\ud55c \uad50\uc721\uacfc \uc548\uc804\uad00\ub9ac\uac00 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uacbd\uc6b0\uc5d0\ub3c4 \ud2b9\uc815 \uc704\ud5d8\uc774 \uc644\uc804\ud788 \uc81c\uac70\ub420 \uc218 \uc5c6\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc704\ud5d8\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc74c\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.a3E=s(["\uc218\uc555 \ubcc0\ud654\uc5d0 \ub530\ub978 \uadc0, \ubd80\ube44\ub3d9, \ud3d0 \ub4f1\uc758 \uc555\ub825 \uc190\uc0c1","\uac10\uc555\ubcd1, \ub3d9\ub9e5\uac00\uc2a4\uc0c9\uc804\uc99d \ubc0f \uae30\ud0c0 \uc7a0\uc218 \uad00\ub828 \uc9c8\ud658","\ud638\ud761 \uae30\uccb4 \uacf5\uae09 \ubb38\uc81c, \uc7a5\ube44 \uace0\uc7a5 \ubc0f \uc0ac\uc6a9\uc0c1\uc758 \uc624\ub958","\uc218\uc911 \ubc29\ud5a5\uac10\uac01 \uc0c1\uc2e4, \uc2dc\uc57c \uc81c\ud55c, \ud574\ub958 \ubc0f \uc218\uc628 \ubcc0\ud654","\ubd80\ub825 \uc870\uc808 \ubb38\uc81c, \ube44\uc0c1\uc0c1\ud669 \ubc0f \uc608\uae30\uce58 \ubabb\ud55c \uc218\uc911 \ud658\uacbd \ubcc0\ud654","\uc2e0\uccb4\uc801 \ud53c\ub85c, \uc2ec\ub9ac\uc801 \uc2a4\ud2b8\ub808\uc2a4 \ubc0f \uac74\uac15 \uc0c1\ud0dc\uc640 \uad00\ub828\ub41c \uc704\ud5d8","\uc2e0\uc18d\ud55c \uad6c\uc870 \ub610\ub294 \uc804\ubb38 \uc758\ub8cc\uae30\uad00\uc73c\ub85c\uc758 \uc774\uc1a1\uc774 \uc5b4\ub824\uc6b4 \ud658\uacbd\uc801 \uc704\ud5d8"],t.s)
