B.a_K=s(["\ubcf8\uc778\uc740 \ub2e4\uc774\ube59 \ucc38\uac00\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\ub294 \ubcf8\uc778\uc758 \uac74\uac15 \uc0c1\ud0dc\ub97c \uc815\ud655\ud558\uac8c \uace0\uc9c0\ud560 \ucc45\uc784\uc774 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ubcc4\ub3c4\ub85c \uc81c\uacf5\ub418\ub294 \ub2e4\uc774\ubc84 \uac74\uac15\uc9c4\uc220\uc11c \ub610\ub294 \uc758\ud559\uc801 \ud3c9\uac00 \uc808\ucc28\uc5d0 \uc131\uc2e4\ud558\uac8c \uc751\ud558\uace0, \uc758\ud559\uc801 \ud655\uc778\uc774 \ud544\uc694\ud55c \uacbd\uc6b0 \uc801\uc808\ud55c \ud655\uc778\uc744 \ubc1b\uc740 \ud6c4 \ucc38\uac00\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\uad50\uc721 \uc911 \uac74\uac15 \uc0c1\ud0dc\uac00 \ubcc0\ud558\uac70\ub098 \uc2e0\uccb4\uc801 \uc774\uc0c1\uc774 \ubc1c\uc0dd\ud558\ub294 \uacbd\uc6b0 \uc989\uc2dc \uac15\uc0ac\uc5d0\uac8c \uc54c\ub9ac\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.arL=new A.eo("\uc81c3\uc870. \uac74\uac15 \uc0c1\ud0dc\uc758 \ud655\uc778",B.a_K,B.C)
B.a2s=s(["\ubcf8\uc778\uc740 APDI \uad50\uc721\uacfc\uc815\uc5d0 \ucc38\uac00\ud558\uba74\uc11c \ub2f4\ub2f9 \uac15\uc0ac\uc758 \uc548\uc804\uad50\uc721, \uad50\uc721 \ubc94\uc704, \uc218\uc911\ud65c\ub3d9 \uacc4\ud68d \ubc0f \ube44\uc0c1\uc0c1\ud669 \uc9c0\uce68\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uad50\uc721\uacfc\uc815\uc5d0\uc11c \uc694\uad6c\ud558\ub294 \uc548\uc804\uc218\uce59, \uc7a5\ube44 \uc810\uac80, \ubc84\ub514 \uc2dc\uc2a4\ud15c, \uc218\uc911 \uc758\uc0ac\uc18c\ud1b5 \ubc0f \ube44\uc0c1\uc808\ucc28\uc758 \uc911\uc694\uc131\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc790\uc2e0\uc758 \uad50\uc721 \uc218\uc900, \uacbd\ud5d8 \ubc0f \uc2e0\uccb4\uc801 \ub2a5\ub825\uc744 \ucd08\uacfc\ud558\ub294 \ud65c\ub3d9\uc744 \uc784\uc758\ub85c \uc218\ud589\ud558\uc9c0 \uc54a\uc73c\uba70, \uc704\ud5d8\ud558\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uc0c1\ud669\uc5d0\uc11c\ub294 \ud65c\ub3d9\uc758 \uc911\ub2e8\uc744 \uc694\uccad\ud560 \uc218 \uc788\uc74c\uc744 \ud655\uc778\ud569\ub2c8\ub2e4."],t.s)
B.arQ=new A.eo("\uc81c4\uc870. \uad50\uc721 \ubc0f \uc548\uc804\uc218\uce59 \uc900\uc218",B.a2s,B.C)
B.a1s=s(["\ubcf8\uc778\uc740 APDI\uac00 \ub2e4\uc774\ubc84 \uad50\uc721\uacfc\uc815\uc758 \uae30\uc900\uacfc \uad50\uc721\uccb4\uacc4\ub97c \uc218\ub9bd\ud558\ub294 \uc804\ubb38 \uad50\uc721\ub2e8\uccb4\uc774\uba70, \uac1c\ubcc4 \uad50\uc721\uae30\uad00\uacfc \uac15\uc0ac\ub294 \ubcc4\ub3c4\uc758 \uc0ac\uc5c5\uc790\ub85c \ud65c\ub3d9\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uac01 \uae30\uad00\uacfc \uac15\uc0ac\uc758 \uad6c\uccb4\uc801\uc778 \ucc45\uc784\uc740 \uc2e4\uc81c \uc6b4\uc601\uad00\uacc4, \uad50\uc721\uacc4\uc57d, \uad00\ub828 \ubc95\ub839 \ubc0f \uac1c\ubcc4 \uc0ac\uc2e4\uad00\uacc4\uc5d0 \ub530\ub77c \ud310\ub2e8\ub420 \uc218 \uc788\uc74c\uc744 \uc778\uc815\ud569\ub2c8\ub2e4."],t.s)
